      "kind": "component_group",
      "quote": "FORWARD COLLISION AVOIDANCE: ADAPTIVE CRUISE CONTROL"
    },
    {
      "kind": "symptom",
      "quote": "Multipurpose camera facing front on top of windshield works intermittently."
    },
    {
      "kind": "condition",
      "quote": "usually the first drive of the morning when the car is cool"
    },
    {
      "kind": "condition",
      "quote": "within 60 seconds upon startup"
    },
    {
      "kind": "symptom",
      "quote": "5 bright orange warning lights that come on all related to a malfunction in the multipurpose camera"
    },
    {
      "kind": "symptom",
      "quote": "Adaptive Cruise Control Failure"
    },
    {
      "kind": "symptom",
      "quote": "Collision Mitigation System Failure"
    },
    {
      "kind": "symptom",
      "quote": "Lane Keeping Assistance Problem"
    },
    {
      "kind": "symptom",
      "quote": "Road Departure Assistance Problem"
    },
    {
      "kind": "symptom",
      "quote": "Auto-High Beam failure"
    },
    {
      "kind": "safety",
      "quote": "Most concerning is that the “BRAKE SYSTEM” light stays illuminated orange after these warnings come on."
    },
    {
      "kind": "condition",
      "quote": "the camera overheating"
    },
    {
      "kind": "condition",
      "quote": "If you pour water on the windshield outside it will cool it off enough to work again."
    },
    {
      "kind": "other",
      "quote": "This started 1 month ago, out of the blue."
